+      await request(app).get('/inscricoes').set('X-Usuario', ORGANIZACAO);
+
+      const minhas = await request(app).get('/inscricoes').set('X-Usuario', PARTICIPANTE);
+      const minha = minhas.body.find((i: any) => i.atividadeId === palestra.id);
