async function registrarPresenca(dia: number, encontros: any[]) {
  const encontro = encontros.find((enc) => enc.inicio.startsWith(`2026-10-${dia}T`));
  if (!encontro) return;
  await definirRelogio(`2026-10-${dia}T19:30:00-03:00`);
